use rvn_core::{Engine,Renderer,renderer::SceneRenderBatch,random::RandomState,types::SpriteState};
use rvn_parser::{Value,Statement,Position,Transition,Hotspot,ParsedProgram};
use std::sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}};
#[derive(Clone,Default)]struct Host{batches:Arc<Mutex<Vec<SceneRenderBatch>>>,reject:Arc<AtomicBool>}
impl Renderer for Host{
 fn validate_scene_batch(&self,_:&SceneRenderBatch)->Result<(),String>{VALIDATIONS.fetch_add(1,Ordering::SeqCst);if FENCED.load(Ordering::SeqCst){return Err("renderer validation reentered Source fence".into());}if self.reject.load(Ordering::SeqCst){Err("fixture preflight failure".into())}else{Ok(())}}
 fn publish_scene_batch(&mut self,b:SceneRenderBatch){self.batches.lock().unwrap().push(b);}
 fn supports_accessibility(&self)->bool{true}fn validate_accessibility_speech(&self,_:&rvn_ui::accessibility::SpeechRequest)->Result<(),String>{Ok(())}
 fn supports_composable_motion(&self)->bool{true}fn supports_video(&self)->bool{true}fn supports_layered_characters(&self)->bool{true}fn supports_programmable_ui(&self)->bool{true}
 fn supports_custom_canvas(&self)->bool{true}
 fn update_videos(&mut self,_:&[rvn_core::video::VideoView])->Result<(),String>{Ok(())}fn update_motions(&mut self,_:&[rvn_core::motion::MotionView])->Result<(),String>{Ok(())}fn update_interfaces(&mut self,_:&[rvn_ui::programmable::ScreenView])->Result<(),String>{Ok(())}fn update_layered_characters(&mut self,_:&[rvn_core::composition::LayeredView])->Result<(),String>{Ok(())}
 fn set_background(&mut self,_:&str,_:&Transition){}fn show_sprite(&mut self,_:&str,_:Option<&str>,_:&Position,_:&Transition,_:Option<&SpriteState>){}fn hide_sprite(&mut self,_:&str,_:&Transition,_:&SpriteState){}fn move_sprite(&mut self,_:&str,_:&Position,_:&Transition,_:&SpriteState){}fn show_dialogue(&mut self,_:Option<&str>,_:&str){}fn show_choice(&mut self,_:&[String])->usize{0}fn show_imagemap(&mut self,_:&str,_:Option<&str>,_:&[Hotspot])->usize{0}fn music_play(&mut self,_:&str,_:&Transition,_:Option<&str>){}fn music_stop(&mut self,_:&Transition){}fn music_set_volume(&mut self,_:f32){}fn sfx_play(&mut self,_:&str,_:&Transition){}fn sfx_stop(&mut self,_:&str,_:&Transition){}
}

use std::sync::atomic::AtomicUsize;
static FENCED:AtomicBool=AtomicBool::new(false);
static VALIDATIONS:AtomicUsize=AtomicUsize::new(0);
#[path="private_pcm0370/checkpoint_pcm.rs"]mod pcm;
#[path="private_pcm0370/frame_pcm_host.rs"]mod real_pcm0370;
const STORY:&str=r#"flow.consume_v2("actual_audio","play"){sfx.play("host.wav") with fade(1000)}
"first"
flow.consume_v2("actual_audio","volume"){music.volume("0.4")}
"second""#;
fn actual()->Engine<real_pcm0370::PcmHost>{actual_from(STORY)}
fn actual_from(story:&str)->Engine<real_pcm0370::PcmHost>{let p=rvn_parser::parse_program(story).unwrap();let mut e=Engine::from_program_with_debugger(p,real_pcm0370::PcmHost::default(),8).unwrap();e.renderer.bind_actual(&e.state,e.instance_id(),e.runtime_epoch()).unwrap();e.step_until_interaction().unwrap();let target=e.audio_playback_views().unwrap()[0].token.target.clone();e.renderer.pull(&target,7).unwrap();record(&mut e);e.advance_dialogue().unwrap();e.step_until_interaction().unwrap();record(&mut e);e}
fn record(e:&mut Engine<real_pcm0370::PcmHost>){let source=e.audio_publication_source().unwrap();let snapshot=e.renderer.capture_audio_checkpoint(&e.state,e.instance_id(),e.runtime_epoch()).unwrap();assert!(e.record_audio_publication(&source,snapshot).unwrap());}
fn wire(e:&Engine<real_pcm0370::PcmHost>)->serde_json::Value{serde_json::json!({"state":e.state,"history":format!("{:?}",e.history.entries()),"epoch":e.runtime_epoch(),"interface":e.interface_epoch(),"publication":e.renderer.publication_count()})}

use rvn_core::engine::PreparedAudioRollback;
use rvn_core::audio_checkpoint::{AudioCheckpointSnapshot,AudioCheckpointRow,MusicCheckpoint};
struct FenceFlag;impl Drop for FenceFlag{fn drop(&mut self){FENCED.store(false,Ordering::SeqCst);}}
fn sources(batch:&SceneRenderBatch)->(pcm::CheckpointGate,Vec<rvn_core::audio_playback::AudioPlaybackView>,Vec<rvn_core::audio_checkpoint::MusicCheckpointView>,Vec<pcm::CheckpointPcm>){let gate=pcm::CheckpointGate::default();let shots=rvn_core::audio_playback::describe(&batch.state,batch.runtime_epoch).unwrap();let music=rvn_core::audio_checkpoint::music_views(&batch.state,batch.runtime_epoch).unwrap();let file=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().parent().unwrap().join("fixtures/pcm/host.wav");let bytes=std::fs::read(file).unwrap();let readers=shots.iter().map(|v|(&v.playback.file,v.playback.checkpoint.as_ref().unwrap(),v.parked)).chain(music.iter().map(|v|(&v.file,v.checkpoint.as_ref().unwrap(),v.parked))).map(|(file,cp,parked)|pcm::PcmClip::decode(file,&bytes).unwrap().restore(gate.clone(),cp,parked).unwrap()).collect();(gate,shots,music,readers)}
fn commit(e:&mut Engine<real_pcm0370::PcmHost>,p:PreparedAudioRollback,mode:&str)->Result<(),String>{let batch=p.render_batch();let(gate,shots,music,readers)=sources(batch);let instance=e.instance_id();let epoch=batch.runtime_epoch;let guard=e.begin_prepared_audio_rollback_commit(p).map_err(|e|e.to_string())?;let count=VALIDATIONS.load(Ordering::SeqCst);let bindings=readers.iter().map(|r|(r,false)).collect::<Vec<_>>();let result=gate.publish(&bindings,|cursors|{let mut snapshot=AudioCheckpointSnapshot{instance_id:instance,runtime_epoch:epoch,rows:shots.iter().zip(&cursors).map(|(v,c)|AudioCheckpointRow{token:v.token.clone(),checkpoint:c.clone()}).collect(),music:music.iter().zip(cursors.iter().skip(shots.len())).map(|(v,c)|MusicCheckpoint{target:v.authority.target.clone(),file:v.file.clone(),checkpoint:c.clone()}).collect()};match mode{"epoch"=>snapshot.runtime_epoch+=1,"target"=>snapshot.rows[0].token.target.incarnation+=1,"cursor"=>{let c=&mut snapshot.rows[0].checkpoint;c.next_sample+=1;c.next_channel=(c.next_sample%u64::from(c.channels))as u16;},"missing"=>snapshot.rows.clear(),"duplicate"=>snapshot.rows.push(snapshot.rows[0].clone()),"instance"=>snapshot.instance_id+=1,"ok"=>{},_=>unreachable!()};FENCED.store(true,Ordering::SeqCst);let _flag=FenceFlag;guard.commit_with_audio_checkpoint(snapshot).map_err(|e|e.to_string())});assert_eq!(VALIDATIONS.load(Ordering::SeqCst),count,"commit reentered renderer under an actual Source gate");result}
#[test]fn prepared_rollback_commits_from_actual_wav_sources_without_renderer_reentry_under_gate(){let mut e=actual();let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let before=wire(&e);let debug=e.debug_state_source().unwrap();let prepared=e.prepare_audio_rollback(&source).unwrap();assert_eq!(wire(&e),before);assert!(e.accepts_debug_state_source(&debug));let target=e.audio_playback_views().unwrap()[0].token.target.clone();let epoch=e.runtime_epoch();commit(&mut e,prepared,"ok").unwrap();assert_eq!(e.runtime_epoch(),epoch+1);assert_eq!(e.state.music.volume,1.0);assert_eq!(e.renderer.cursor(&target).unwrap().next_sample,7);assert!(!e.accepts_audio_rollback_source(&source));}
#[test]fn old_direct_rollback_would_reenter_renderer_inside_gate_and_refuses_before_mutation(){let mut e=actual();let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let prepared=e.prepare_audio_rollback(&source).unwrap();let(gate,_,_,readers)=sources(prepared.render_batch());let before=wire(&e);let count=VALIDATIONS.load(Ordering::SeqCst);gate.publish(&readers.iter().map(|r|(r,false)).collect::<Vec<_>>(),|_|{FENCED.store(true,Ordering::SeqCst);let _flag=FenceFlag;let error=e.rollback_from_audio_source(&source).unwrap_err();assert!(error.to_string().contains("renderer validation reentered Source fence"));Ok(())}).unwrap();assert!(VALIDATIONS.load(Ordering::SeqCst)>count);assert_eq!(wire(&e),before);}
#[test]fn invalid_fenced_snapshot_never_pops_history_reallocates_epochs_or_publishes(){for mode in ["epoch","target","cursor","missing","duplicate","instance"]{let mut e=actual();let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let prepared=e.prepare_audio_rollback(&source).unwrap();let before=wire(&e);let debug=e.debug_state_source().unwrap();assert!(commit(&mut e,prepared,mode).is_err(),"{mode} admitted");assert_eq!(wire(&e),before);assert!(e.accepts_debug_state_source(&debug));assert!(e.accepts_audio_rollback_source(&source));}}
#[test]fn dropped_or_stale_preparation_preserves_history_and_current_sources(){let mut e=actual();let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let before=wire(&e);let prepared=e.prepare_audio_rollback(&source).unwrap();drop(e.begin_prepared_audio_rollback_commit(prepared).unwrap());assert_eq!(wire(&e),before);let prepared=e.prepare_audio_rollback(&source).unwrap();e.tick_game_frame(0.125,Default::default()).unwrap();let changed=wire(&e);assert!(!e.accepts_prepared_audio_rollback(&prepared));assert!(e.begin_prepared_audio_rollback_commit(prepared).is_err());assert_eq!(wire(&e),changed);}

#[test]fn real_scene_history_and_owner_use_the_same_prepared_fence_without_fabricated_game_registry(){let p=rvn_parser::parse_program(&format!("scene label start\n{STORY}")).unwrap();let mut e=Engine::from_program_with_debugger(p,real_pcm0370::PcmHost::default(),8).unwrap();e.renderer.bind_actual(&e.state,e.instance_id(),e.runtime_epoch()).unwrap();e.step().unwrap();let target=e.audio_playback_views().unwrap()[0].token.target.clone();e.renderer.pull(&target,7).unwrap();record(&mut e);let mut session=e.debug_begin(rvn_core::engine::DebugOperation::Statement,vec![]).unwrap();for _ in 0..32{if e.debug_step(&mut session,rvn_core::editor_debugger::StepKind::Continue).unwrap().0==rvn_core::engine::DebugProgress::Complete{break;}}assert_eq!(e.state.music.volume,0.4);assert!(e.state.game_audio.is_none());let owner=e.state.scene_execution.as_ref().unwrap().owner().unwrap();let token=e.audio_playback_views().unwrap()[0].token.clone();assert_eq!(token.task.key.owner,rvn_core::scene_tasks::TaskOwner::Scene{activation:owner});let source=e.preview_game_audio_rollback_source().unwrap().unwrap();let prepared=e.prepare_audio_rollback(&source).unwrap();commit(&mut e,prepared,"ok").unwrap();assert!(e.state.game_audio.is_none());assert_eq!(e.state.scene_execution.as_ref().unwrap().owner(),Some(owner));assert_eq!(e.state.music.volume,1.0);assert_eq!(e.renderer.cursor(&token.target).unwrap().next_sample,7);}
